# The Joomla family (edjobs::fetch_joomla_postings(), edjobs 0.23.0, 2026-11-14;
# claude-notes/2026-11-14_small-families/joomla/): each registry row, with its own Job_Link, City and
# k12_list_rules.csv rule, against the district's captured page(s). Expected titles are the routine's output,
# checked against each district's old parser (every difference listed in the README).
# Test titles name the parser and the district so the auto-fix issue finds that district's fixtures.
# Generated by claude-notes/2026-11-14_small-families/joomla/make_family_test.R.

joomla_parse <- function(district, fixture) {
  reg <- read.csv(here::here("k12_district_registry.csv"), stringsAsFactors = FALSE)
  row <- reg[reg$District == district, ]
  expect_equal(nrow(row), 1)
  expect_equal(row$Platform, "Joomla")
  rules <- read_k12_list_rules(here::here("k12_list_rules.csv"))
  html <- paste(readLines(fixture, warn = FALSE, encoding = "UTF-8"), collapse = "\n")
  r <- parse_joomla_postings(html, row$Job_Link, row$City, k12_list_rule(rules, district, "List_Start"),
                                  k12_list_rule(rules, district, "List_Stop"), k12_list_rule(rules, district, "Skip_Section"))
  expect_true(all(r$Location == row$City))
  r
}

test_that("parse_joomla_postings: Roy School District 74", {
  r <- joomla_parse("Roy School District 74", test_path("fixtures", "roy_employment.html"))
  expect_equal(r$Title, c("Head Cook",
      "Full-time Paraprofessional",
      "BUS DRIVER"))
})

test_that("parse_joomla_postings: Joliet Public School District 86", {
  r <- joomla_parse("Joliet Public School District 86", test_path("fixtures", "joliet_jobs.html"))
  expect_equal(r$Title, c("Bus Route & Bus Route Sub Drivers",
      "Substitute Teachers",
      "Head High School Boys Basketball Coach",
      "Asst High School Girls Basketball Coach",
      "Head High School Boys/Girls Golf Coach"))
})

test_that("parse_joomla_postings: Roberts Public School", {
  r <- joomla_parse("Roberts Public School", test_path("fixtures", "roberts_employment.html"))
  expect_equal(r$Title, c("Full Time Custodian",
      "Substitute Teachers Needed",
      "Classroom Aide"))
})

test_that("parse_joomla_postings: Belfry Public Schools", {
  r <- joomla_parse("Belfry Public Schools", test_path("fixtures", "belfry_employment_2026-10-20.html"))
  expect_equal(r$Title, c("Substitute Teachers",
      "School Bus Drivers"))
})

test_that("parse_joomla_postings: Luther School", {
  r <- joomla_parse("Luther School", test_path("fixtures", "luther_documents_2026-10-21.html"))
  expect_equal(r$Title, c("Bus Driver",
      "Cook"))
})

test_that("every Joomla registry row resolves to the family routine", {
  reg <- read.csv(here::here("k12_district_registry.csv"), stringsAsFactors = FALSE)
  for (d in reg$District[reg$Platform == "Joomla"]) expect_equal(edjobs::resolve_scraper_call(d)$fn, "fetch_joomla_postings", info = d)
  expect_equal(edjobs::resolve_scraper_call("Roy School District 74")$fn, "fetch_joomla_postings")
})
